mapper.select:
SELECT pm.admin_dong_id, pm.house_type, pm.avg_deposit, pm.avg_rent, pm.avg_area FROM property_metrics pm JOIN ( SELECT admin_dong_id, house_type, MAX(property_metric_id) AS latest_property_metric_id FROM property_metrics WHERE admin_dong_id IN
#{adminDongId}
AND rental_type = #{rentalType} AND house_type IN
#{houseType}
GROUP BY admin_dong_id, house_type ) latest ON latest.admin_dong_id = pm.admin_dong_id AND latest.house_type = pm.house_type AND latest.latest_property_metric_id = pm.property_metric_id
